REVOKE ALL ON TABLE public."transactions" FROM PUBLIC, anon, authenticated, service_role, agsaas_app;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public."transactions" TO agsaas_app, service_role;
REVOKE ALL ON TABLE public."user_invites" FROM PUBLIC, anon, authenticated, service_role, agsaas_app;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public."user_invites" TO agsaas_app, service_role;
REVOKE ALL ON TABLE public."users" FROM PUBLIC, anon, authenticated, service_role, agsaas_app;
